[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='High')]
param([ValidateSet('Check','Capture','DryRun','Apply','Verify','VerifyReboot','Rollback')][string]$Action='Check',[string]$StatePath,[string]$LogPath)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$experiment='EXP-095';$provider='hp-casl-delayed-start';$profile='HPCaslDelayedStart';$serviceName='hpqcaslwmiex'
$protected='(?i)omnissa|vmware horizon|windows app|remote desktop|mstsc|tailscale|defender|securityhealth|firewall|bitlocker|credential|windows update|recovery|intune|sccm|configmgr|mdm|vpn|ndis'
function Write-Log([string]$Event,[string]$Result,[object]$Data){if([string]::IsNullOrWhiteSpace($LogPath)){return};$p=Split-Path -Parent $LogPath;if($p-and!(Test-Path -LiteralPath $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null};[ordered]@{schemaVersion=1;timestampUtc=(Get-Date).ToUniversalTime().ToString('o');experiment=$experiment;provider=$provider;action=$Action;event=$Event;result=$Result;machine=$env:COMPUTERNAME;userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;data=$Data}|ConvertTo-Json -Compress -Depth 24|Add-Content -LiteralPath $LogPath -Encoding UTF8}
function Get-Hash([string]$Text){$s=[Security.Cryptography.SHA256]::Create();try{($s.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text))|ForEach-Object{$_.ToString('x2')})-join''}finally{$s.Dispose()}}
function Get-ManagementState{$c=Get-CimInstance Win32_ComputerSystem;$x=[ordered]@{DomainJoined=[bool]$c.PartOfDomain;MdmEnrollments=@(Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Enrollments' -ErrorAction SilentlyContinue).Count;PolicyManager=Test-Path 'HKLM:\SOFTWARE\Microsoft\PolicyManager\current\device';ConfigMgr=[bool](Get-Service CcmExec -ErrorAction SilentlyContinue);ServicePolicy=Test-Path "HKLM:\SOFTWARE\Policies\Lacksan\Services\$serviceName";Provisioning=Test-Path 'HKLM:\SOFTWARE\Microsoft\Provisioning'};[pscustomobject]@{Managed=($x.DomainJoined-or$x.MdmEnrollments-gt0-or$x.PolicyManager-or$x.ConfigMgr-or$x.ServicePolicy);Signals=$x}}
function Get-SupportState{$o=Get-CimInstance Win32_OperatingSystem;$c=Get-CimInstance Win32_ComputerSystem;$id=[Security.Principal.WindowsIdentity]::GetCurrent();$admin=(New-Object Security.Principal.WindowsPrincipal($id)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator);$m=Get-ManagementState;$bios=Get-CimInstance Win32_BIOS;[pscustomobject]@{Supported=($o.Caption-match'Windows 11'-and$c.Manufacturer-match'(?i)^HP$|Hewlett-Packard'-and$admin);Elevated=$admin;OS=$o.Caption;Build=$o.BuildNumber;Manufacturer=$c.Manufacturer;Model=$c.Model;BIOS=$bios.SMBIOSBIOSVersion;Managed=$m.Managed;ManagementSignals=$m.Signals}}
function Get-ProtectedSnapshot{$configSvc=foreach($n in 'WinDefend','mpssvc','wuauserv','UsoSvc','BITS','Tailscale'){$x=Get-CimInstance Win32_Service -Filter "Name='$n'" -ErrorAction SilentlyContinue;if($x){[ordered]@{Name=$x.Name;StartMode=$x.StartMode;PathName=$x.PathName}}};$runtimeSvc=foreach($n in 'WinDefend','mpssvc','wuauserv','UsoSvc','BITS','Tailscale'){$x=Get-CimInstance Win32_Service -Filter "Name='$n'" -ErrorAction SilentlyContinue;if($x){[ordered]@{Name=$x.Name;State=$x.State}}};$proc=@(Get-Process -ErrorAction SilentlyContinue|Where-Object{$_.ProcessName-match'(?i)omnissa|horizon|msrdc|mstsc|tailscale'}|Select-Object -ExpandProperty ProcessName -Unique|Sort-Object);$configuration=[ordered]@{Services=@($configSvc)}|ConvertTo-Json -Compress -Depth 8;$runtime=[ordered]@{Services=@($runtimeSvc);Processes=$proc}|ConvertTo-Json -Compress -Depth 8;[pscustomobject]@{Hash=Get-Hash $configuration;Configuration=$configuration;Runtime=$runtime}}
function Resolve-Exe([string]$PathName){$e=[Environment]::ExpandEnvironmentVariables($PathName).Trim();if($e-match$protected){return $null};if($e-match'^\s*"(?<exe>[^"]+)"'){$p=$matches.exe}elseif($e-match'^\s*(?<exe>\S+\.exe)'){$p=$matches.exe}else{return $null};try{[IO.Path]::GetFullPath($p)}catch{return $null}}
function Get-PackageInventory([string]$Exe){$roots='HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall';$parent=Split-Path -Parent $Exe;$items=foreach($r in $roots){Get-ChildItem $r -ErrorAction SilentlyContinue|ForEach-Object{$p=Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue;if($p.Publisher-match'(?i)HP|Hewlett-Packard' -and (($p.DisplayName-match'(?i)CASL') -or ($p.InstallLocation -and $parent.StartsWith([string]$p.InstallLocation,[StringComparison]::OrdinalIgnoreCase)))){[ordered]@{Key=$_.PSChildName;DisplayName=$p.DisplayName;DisplayVersion=$p.DisplayVersion;Publisher=$p.Publisher;InstallLocation=$p.InstallLocation}}}};@($items)}
function Get-Identity{$all=@(Get-CimInstance Win32_Service -Filter "Name='$serviceName'");if($all.Count-ne1){return $null};$s=$all[0];$exe=Resolve-Exe $s.PathName;if(!$exe-or$exe-notmatch'(?i)\\(HP|Hewlett-Packard)\\.*hpqcaslwmiex\.exe$'){return $null};if(!(Test-Path -LiteralPath $exe -PathType Leaf)){return $null};$f=Get-Item -LiteralPath $exe;$sig=Get-AuthenticodeSignature -LiteralPath $exe;$pub=if($sig.SignerCertificate){$sig.SignerCertificate.Subject}else{$null};$deps=@($s.Dependencies);$dependents=@((Get-Service $serviceName).DependentServices|ForEach-Object{$_.Name});$key="HKLM:\SYSTEM\CurrentControlSet\Services\$serviceName";$delayed=(Get-ItemProperty -LiteralPath $key -Name DelayedAutoStart -ErrorAction SilentlyContinue).DelayedAutoStart;$failure=(& sc.exe qfailure $serviceName 2>&1|Out-String).Trim();$triggers=(& sc.exe qtriggerinfo $serviceName 2>&1|Out-String).Trim();$packages=Get-PackageInventory $exe;[pscustomobject]@{Name=$s.Name;DisplayName=$s.DisplayName;State=$s.State;StartMode=$s.StartMode;DelayedAutoStart=[int]($null-ne$delayed-and[int]$delayed-ne0);PathName=$s.PathName;ServiceAccount=$s.StartName;Dependencies=@($deps);Dependents=@($dependents);RecoveryActions=$failure;Triggers=$triggers;Packages=@($packages);Executable=[ordered]@{Path=$f.FullName;Sha256=(Get-FileHash -LiteralPath $exe -Algorithm SHA256).Hash;FileVersion=$f.VersionInfo.FileVersion;ProductName=$f.VersionInfo.ProductName;CompanyName=$f.VersionInfo.CompanyName;SignatureStatus=$sig.Status.ToString();Publisher=$pub;Thumbprint=if($sig.SignerCertificate){$sig.SignerCertificate.Thumbprint}else{$null};ValidPublisher=($sig.Status-eq'Valid'-and$pub-match'(?i)HP Inc|Hewlett-Packard')}}}
function Assert-Eligible($Support,$Identity){if(!$Support.Supported){throw 'Elevated HP Windows 11 is required.'};if($Support.Managed){throw 'Enterprise-management ownership detected.'};if($null-eq$Identity){throw 'Exactly one hpqcaslwmiex identity is required.'};if($Identity.DisplayName-notmatch'(?i)^HP CASL Framework Service$'){throw 'Service display identity mismatch.'};if(!$Identity.Executable.ValidPublisher){throw 'Valid HP publisher signature is required.'};if($Identity.StartMode-notin @('Auto','Automatic')){throw 'Baseline service start mode must be Automatic.'};if($Identity.DelayedAutoStart-ne0){throw 'Service is already delayed.'};if($Identity.Dependencies -match $protected -or $Identity.Dependents -match $protected){throw 'Protected dependency detected.'};if($Identity.Triggers -and $Identity.Triggers-notmatch'(?i)(service has no trigger|no triggers|no trigger events registered|ERROR 1060)'){throw 'Trigger-sensitive service state detected.'};if($Identity.RecoveryActions-match'(?im)^\s*REBOOT_MESSAGE\s*:\s*\S+' -or $Identity.RecoveryActions-match'(?im)^\s*COMMAND_LINE\s*:\s*\S+'){throw 'Recovery-sensitive service state detected.'};if($Identity.Packages.Count-ne1){throw 'Exactly one associated HP CASL package identity is required.'}}
function Save-State($Support,$Identity){Assert-Eligible $Support $Identity;if([string]::IsNullOrWhiteSpace($StatePath)){throw 'StatePath is required.'};if(Test-Path -LiteralPath $StatePath){throw 'State overwrite refused.'};$p=Get-ProtectedSnapshot;$depJson=[ordered]@{Dependencies=@($Identity.Dependencies);Dependents=@($Identity.Dependents)}|ConvertTo-Json -Compress;$s=[ordered]@{schemaVersion=1;experiment=$experiment;provider=$provider;capturedUtc=(Get-Date).ToUniversalTime().ToString('o');capturedBootTime=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime().ToString('o');machine=$env:COMPUTERNAME;userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;support=$Support;protectedScopeHash=$p.Hash;protectedRuntime=$p.Runtime;dependencyHash=Get-Hash $depJson;service=$Identity};$parent=Split-Path -Parent $StatePath;if($parent-and!(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};$s|ConvertTo-Json -Depth 24|Set-Content -LiteralPath $StatePath -Encoding UTF8;$s}
function Read-State{if([string]::IsNullOrWhiteSpace($StatePath)-or!(Test-Path -LiteralPath $StatePath)){throw 'State artifact is missing.'};$s=Get-Content -LiteralPath $StatePath -Raw|ConvertFrom-Json;$sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;if($s.schemaVersion-ne1-or$s.experiment-ne$experiment-or$s.provider-ne$provider-or$s.machine-ne$env:COMPUTERNAME-or$s.userSid-ne$sid){throw 'State identity validation failed.'};$s}
function Assert-Identity($State){$i=Get-Identity;if($null-eq$i-or$i.Executable.Sha256-ne[string]$State.service.Executable.Sha256-or$i.Executable.Thumbprint-ne[string]$State.service.Executable.Thumbprint-or$i.PathName-ne[string]$State.service.PathName){throw 'Service or executable identity drift detected.'};$d=[ordered]@{Dependencies=@($i.Dependencies);Dependents=@($i.Dependents)}|ConvertTo-Json -Compress;if((Get-Hash $d)-ne[string]$State.dependencyHash){throw 'Dependency drift detected.'};if($i.Packages.Count-ne1-or$i.Packages[0].Key-ne[string]$State.service.Packages[0].Key-or$i.Packages[0].DisplayVersion-ne[string]$State.service.Packages[0].DisplayVersion){throw 'Package identity drift detected.'};$i}
function Set-Delayed([int]$Delayed){Set-Service -Name $serviceName -StartupType Automatic;$key="HKLM:\SYSTEM\CurrentControlSet\Services\$serviceName";if($Delayed-eq1){Set-ItemProperty -LiteralPath $key -Name DelayedAutoStart -Type DWord -Value 1}else{Remove-ItemProperty -LiteralPath $key -Name DelayedAutoStart -ErrorAction SilentlyContinue}}
try{$support=Get-SupportState;Write-Log 'support-detection' $(if($support.Supported){'pass'}else{'unsupported'}) $support;switch($Action){
'Check'{$i=Get-Identity;Write-Log 'service-inventory' 'pass' @{found=[bool]$i;name=if($i){$i.Name}else{$null};dependents=if($i){$i.Dependents}else{@()};packages=if($i){$i.Packages.Count}else{0}};[pscustomobject]@{Support=$support;Service=$i;Profile=$profile}}
'Capture'{$s=Save-State $support (Get-Identity);Write-Log 'capture' 'pass' @{service=$s.service.Name;startMode=$s.service.StartMode;delayed=$s.service.DelayedAutoStart;state=$s.service.State;dependents=$s.service.Dependents;package=$s.service.Packages;protectedRuntime=$s.protectedRuntime};$s}
'DryRun'{$i=Get-Identity;Assert-Eligible $support $i;$r=[pscustomobject]@{Profile=$profile;WouldChange=$true;MutationCount=1;Service=$serviceName;From='Automatic';To='AutomaticDelayedStart';PreserveRunningState=$true;RebootPersistenceCheckRequired=$true;Rollback='Restore exact captured Automatic startup, delayed-auto-start state, and running state.'};Write-Log 'dry-run' 'pass' $r;$r}
'Apply'{$s=if(Test-Path -LiteralPath $StatePath){Read-State}else{Save-State $support (Get-Identity)};$i=Assert-Identity $s;if($i.StartMode-in @('Auto','Automatic')-and$i.DelayedAutoStart-eq1){Write-Log 'apply' 'idempotent' @{mutationCount=0};return [pscustomobject]@{Applied=$true;MutationCount=0}};Assert-Eligible $support $i;if((Get-ProtectedSnapshot).Hash-ne[string]$s.protectedScopeHash){throw 'Protected-scope configuration drift detected.'};$beforeState=$i.State;if($WhatIfPreference){Write-Log 'apply' 'whatif' @{mutationCount=0};return [pscustomobject]@{Applied=$false;WhatIf=$true;MutationCount=0}};if($PSCmdlet.ShouldProcess($serviceName,'Set Automatic Delayed Start without stopping service')){Set-Delayed 1};$after=Assert-Identity $s;if($after.StartMode-notin @('Auto','Automatic')-or$after.DelayedAutoStart-ne1-or$after.State-ne$beforeState){throw 'Apply verification failed or running state changed.'};Write-Log 'apply' 'pass' @{mutationCount=1;runningStatePreserved=$true};[pscustomobject]@{Applied=$true;MutationCount=1}}
'Verify'{$s=Read-State;$i=Assert-Identity $s;if($i.StartMode-notin @('Auto','Automatic')-or$i.DelayedAutoStart-ne1){throw 'Immediate verification failed.'};Write-Log 'verify' 'pass' @{startMode=$i.StartMode;delayed=$i.DelayedAutoStart;state=$i.State};$true}
'VerifyReboot'{$s=Read-State;$b=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime();if($b-le[datetime]$s.capturedBootTime){throw 'A later boot is required.'};$i=Assert-Identity $s;if($i.StartMode-notin @('Auto','Automatic')-or$i.DelayedAutoStart-ne1-or$i.State-ne'Running'){throw 'Reboot delayed-start persistence or service health verification failed.'};if((Get-ProtectedSnapshot).Hash-ne[string]$s.protectedScopeHash){throw 'Protected-scope configuration drift detected after reboot.'};Write-Log 'verify-reboot' 'pass' @{bootTime=$b.ToString('o');startMode=$i.StartMode;delayed=$i.DelayedAutoStart;state=$i.State;dependents=$i.Dependents;protectedRuntime=(Get-ProtectedSnapshot).Runtime};$true}
'Rollback'{$s=Read-State;$i=Assert-Identity $s;if($support.Managed){throw 'Management ownership appeared.'};if((Get-ProtectedSnapshot).Hash-ne[string]$s.protectedScopeHash){throw 'Protected-scope configuration drift detected.'};if($i.DelayedAutoStart-eq[int]$s.service.DelayedAutoStart-and$i.StartMode-in @('Auto','Automatic')-and$i.State-eq[string]$s.service.State){Write-Log 'rollback' 'idempotent' @{mutationCount=0};return [pscustomobject]@{RolledBack=$true;MutationCount=0}};if($i.StartMode-notin @('Auto','Automatic')-or$i.DelayedAutoStart-ne1){throw 'Rollback configuration drift detected.'};if($WhatIfPreference){Write-Log 'rollback' 'whatif' @{mutationCount=0};return [pscustomobject]@{RolledBack=$false;WhatIf=$true;MutationCount=0}};if($PSCmdlet.ShouldProcess($serviceName,'Restore captured Automatic startup and running state')){Set-Delayed ([int]$s.service.DelayedAutoStart);if([string]$s.service.State-eq'Running' -and (Get-Service $serviceName).Status-ne'Running'){Start-Service $serviceName};if([string]$s.service.State-eq'Stopped' -and (Get-Service $serviceName).Status-ne'Stopped'){Stop-Service $serviceName}};$r=Assert-Identity $s;if($r.StartMode-notin @('Auto','Automatic')-or$r.DelayedAutoStart-ne[int]$s.service.DelayedAutoStart-or$r.State-ne[string]$s.service.State){throw 'Exact rollback verification failed.'};Write-Log 'rollback' 'pass' @{mutationCount=1;restoredExactOriginal=$true};[pscustomobject]@{RolledBack=$true;MutationCount=1}}
}}catch{Write-Log 'failure' 'fail' @{stage=$Action;message=$_.Exception.Message};throw}